// Parse the <visual> block: mode decides whether we render Mermaid or call the image model.
const raw = $input.first().json.text || '';
const grab = (tag) => {
  const m = raw.match(new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>'));
  return m ? m[1].trim() : '';
};
const mode = (grab('mode') || 'hero').toLowerCase();
const mermaid = grab('mermaid').replace(/^```(mermaid)?\s*/, '').replace(/```\s*$/, '').trim();
const imagePrompt = grab('image_prompt');
return [{
  json: {
    mode,
    concept: grab('concept'),
    headline: grab('headline'),
    // Logged, not used downstream: it is how you audit whether the art
    // director actually anchored the metaphor in the post's subject, named the
    // subject it lettered, and invented an emblem instead of a real logo.
    subject_anchor: grab('subject_anchor'),
    wordmark: grab('wordmark'),
    emblem: grab('emblem'),
    text: mode === 'diagram' && mermaid ? mermaid : (imagePrompt || raw),
  },
}];

// Convert the rendered PNG to the same data-URL JSON shape the hero branch produces.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{
  json: {
    'omImage ': JSON.stringify({ url: 'data:image/png;base64,' + buffer.toString('base64') }),
    prompt: $('parse_llm_output').item.json.text,
  },
}];

// Pick the motif vocabulary for this post out of datasets/image_motifs.json and render it
// as the {{ SUBJECT_MOTIFS }} block of prompts/linkedin_image_prompt.md.
//
// Why this node exists: ART_DIRECTION only ever controlled *style*, so the art director had
// no lever for subject at all and kept returning domain-free tension objects - a chalk
// drawing of bare handcuffs for a post about data engineers being automated. It stopped the
// scroll and said nothing about AI. Scoring is keyword-based and deterministic on purpose: a
// wrong domain shows up in the execution log and is fixed in the dataset, where an LLM
// classifier would be a second thing to debug on a 4B model.
const raw = $json.output || '{}';
let cfg;
try {
  cfg = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/image_motifs.json is not valid JSON: ' + e.message);
}

const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const arr = (v, d) => (Array.isArray(v) ? v : d);
const obj = (v, d) => (v && typeof v === 'object' && !Array.isArray(v) ? v : d);
const str = (v) => String(v == null ? '' : v);

// Every knob defaults, so a partial or truncated dataset degrades to the default domain
// instead of taking an image run down.
const domains = obj(cfg.domains, {});
const minScore = num(cfg.min_score, 2);
const maxDomains = Math.max(1, num(cfg.max_domains, 2));
const runnerUpRatio = Math.min(1, Math.max(0, num(cfg.runner_up_ratio, 0.5)));
const defaultDomain = str(cfg.default_domain) || 'default';
const maxAnchors = Math.max(1, num(cfg.max_anchors, 8));
const maxMotifs = Math.max(1, num(cfg.max_motifs, 4));
const maxAvoid = Math.max(1, num(cfg.max_avoid, 8));
const universalAvoid = arr(cfg.universal_avoid, []).map(str).filter(Boolean);

const post = str($('set_workflow_vars').first().json.POST_CONTENT).toLowerCase();

// Whole-word match: "gpu" must not fire inside an unrelated token, and plural/adjective
// forms are listed explicitly in the dataset rather than guessed at with stemming.
const matches = (kw) => {
  const esc = kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9])' + esc + '([^a-z0-9]|$)').test(post);
};

const scored = Object.keys(domains)
  .filter((k) => k !== defaultDomain)
  .map((k) => ({
    key: k,
    score: arr(obj(domains[k], {}).keywords, [])
      .map((s) => str(s).toLowerCase())
      .filter(Boolean)
      .filter(matches).length,
  }))
  .sort((a, b) => b.score - a.score || a.key.localeCompare(b.key));

// A post is routinely two things at once - the reference post was data engineering by
// material and career by tension - and it is the weaker domain that usually holds the
// anchor that saves the image. So runners-up join on a ratio of the top score, not a fixed
// margin, capped because a long list dilutes a small model.
let selected = [];
if (scored.length && scored[0].score >= minScore) {
  const cut = Math.max(minScore, Math.ceil(scored[0].score * runnerUpRatio));
  selected = scored.filter((d) => d.score >= cut).slice(0, maxDomains);
}
if (!selected.length) selected = [{ key: defaultDomain, score: 0 }];

// Rotate the examples within each domain. Domain choice stays deterministic and logged, but
// WHICH anchors and fusions get shown varies per run: the reference post shipped career-craft
// fusion 1 near-verbatim, and without rotation the handful of injected examples would become the
// entire feed. Same Math.random() approach the ART_DIRECTION list in download_image_prompt uses.
const rotate = (list) => {
  const out = list.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = out[i];
    out[i] = out[j];
    out[j] = t;
  }
  return out;
};

// Round-robin across the selected domains rather than concatenating them, so the cap
// cannot spend every slot on the top domain and silently drop the runner-up's fusion
// example - which is the one that carries the post's tension.
const pick = (field, cap) => {
  const pools = selected.map((d) => rotate(arr(obj(domains[d.key], {})[field], []).map(str).filter(Boolean)));
  const seen = new Set();
  const out = [];
  const depth = Math.max(0, ...pools.map((p) => p.length));
  for (let i = 0; i < depth && out.length < cap; i++) {
    for (const pool of pools) {
      if (out.length >= cap) break;
      const v = pool[i];
      if (!v) continue;
      const k = v.toLowerCase();
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(v);
    }
  }
  return out;
};

const anchors = pick('anchors', maxAnchors);
const motifs = pick('motifs', maxMotifs);
const avoid = pick('avoid', maxAvoid);
for (const v of universalAvoid) {
  if (!avoid.some((a) => a.toLowerCase() === v.toLowerCase())) avoid.push(v);
}

const lines = [];
lines.push('Detected subject domain(s): ' + selected.map((d) => d.key + ' [' + d.score + ']').join(', '));
if (anchors.length) {
  lines.push('');
  lines.push("SUBJECT ANCHORS - render this post's subject as one of these concrete things:");
  anchors.forEach((a) => lines.push('- ' + a));
}
if (motifs.length) {
  lines.push('');
  lines.push('EXAMPLE FUSIONS - the degree of fusion required between tension and anchor. Do not reuse one verbatim; produce one of this kind for THIS post:');
  motifs.forEach((m) => lines.push('- ' + m));
}
if (avoid.length) {
  lines.push('');
  lines.push('AVOID - these read as stock AI/tech imagery and are banned:');
  avoid.forEach((a) => lines.push('- ' + a));
}

return [{
  // pairedItem is explicit because download_image_prompt and generate_image both still read
  // $('set_workflow_vars').item, and this node now sits between them and that node.
  pairedItem: { item: 0 },
  json: {
    SUBJECT_MOTIFS: lines.join('\n'),
    // Kept for the execution log: the domain choice is the first thing to check when an
    // image comes back off-subject.
    motif_domains: selected.map((d) => d.key + ':' + d.score),
  },
}];

